# fix-generate-script.ps1
# Run this script from the root of the ViralForge project (same folder as package.json)
$ErrorActionPreference = "Stop"

$targetPath = Join-Path $PSScriptRoot "api\generate-script.js"

if (-not (Test-Path $targetPath)) {
    Write-Host "ERROR: file not found at $targetPath" -ForegroundColor Red
    Write-Host "Make sure fix-generate-script.ps1 is placed directly in the project root (where package.json is)." -ForegroundColor Red
    exit 1
}

$b64 = ""
$bytes = [System.Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes($targetPath, $bytes)

Write-Host "OK: $targetPath updated." -ForegroundColor Green

Set-Location $PSScriptRoot
git add .
git commit -m "Make script parsing resilient to formatting variations"
git push

Write-Host "Committed and pushed. Vercel will redeploy in a minute." -ForegroundColor Green
